import{_ as t,c as e,o as i,ag as r}from"./chunks/framework.CMajxlqO.js";const u=JSON.parse('{"title":"HMI-simulering","description":"","frontmatter":{},"headers":[],"relativePath":"09-test-simulering/hmi-simulering.md","filePath":"09-test-simulering/hmi-simulering.md","lastUpdated":1768470380000}'),l={name:"09-test-simulering/hmi-simulering.md"};function n(s,a,o,d,m,h){return i(),e("div",null,[...a[0]||(a[0]=[r(`<h1 id="hmi-simulering" tabindex="-1">HMI-simulering <a class="header-anchor" href="#hmi-simulering" aria-label="Permalink to &quot;HMI-simulering&quot;">​</a></h1><p>TIA Portal innehåller en inbyggd HMI-simulator som låter dig testa operatörspaneler utan fysisk hårdvara. Genom att kombinera PLCSIM med HMI-simulatorn kan du testa hela systemet virtuellt.</p><h2 id="starta-hmi-runtime-simulation" tabindex="-1">Starta HMI Runtime Simulation <a class="header-anchor" href="#starta-hmi-runtime-simulation" aria-label="Permalink to &quot;Starta HMI Runtime Simulation&quot;">​</a></h2><h3 id="fran-tia-portal" tabindex="-1">Från TIA Portal <a class="header-anchor" href="#fran-tia-portal" aria-label="Permalink to &quot;Från TIA Portal&quot;">​</a></h3><ol><li>Markera din HMI-enhet i projektträdet</li><li>Klicka på <strong>Start simulation</strong> i verktygsfältet (eller tryck Ctrl+Shift+X)</li><li>Simuleringsfönstret öppnas med din HMI-applikation</li></ol><h3 id="alternativ-kompilera-forst" tabindex="-1">Alternativ: Kompilera först <a class="header-anchor" href="#alternativ-kompilera-forst" aria-label="Permalink to &quot;Alternativ: Kompilera först&quot;">​</a></h3><p>Om du gjort ändringar:</p><ol><li>Högerklicka på HMI-enheten</li><li>Välj <strong>Compile &gt; Software (rebuild all)</strong></li><li>Starta sedan simulering</li></ol><h2 id="kombinera-med-plcsim" tabindex="-1">Kombinera med PLCSIM <a class="header-anchor" href="#kombinera-med-plcsim" aria-label="Permalink to &quot;Kombinera med PLCSIM&quot;">​</a></h2><p>För fullständig systemtest:</p><h3 id="steg-1-starta-plcsim-forst" tabindex="-1">Steg 1: Starta PLCSIM först <a class="header-anchor" href="#steg-1-starta-plcsim-forst" aria-label="Permalink to &quot;Steg 1: Starta PLCSIM först&quot;">​</a></h3><ol><li>Ladda ner PLC-projektet till PLCSIM</li><li>Sätt PLC:n i RUN-läge</li><li>Verifiera att programmet körs</li></ol><h3 id="steg-2-starta-hmi-simulering" tabindex="-1">Steg 2: Starta HMI-simulering <a class="header-anchor" href="#steg-2-starta-hmi-simulering" aria-label="Permalink to &quot;Steg 2: Starta HMI-simulering&quot;">​</a></h3><ol><li>Starta HMI-simuleringen</li><li>HMI:n ansluter automatiskt till PLCSIM</li><li>Kommunikationsstatus visas i statusfältet</li></ol><h3 id="verifiering-av-anslutning" tabindex="-1">Verifiering av anslutning <a class="header-anchor" href="#verifiering-av-anslutning" aria-label="Permalink to &quot;Verifiering av anslutning&quot;">​</a></h3><p>I HMI-simuleringen:</p><ul><li>Grönt statusfält = ansluten till PLC</li><li>Rött statusfält = kommunikationsfel</li><li>Varningstriangel = delvis anslutning</li></ul><h2 id="testa-skarmbilder" tabindex="-1">Testa skärmbilder <a class="header-anchor" href="#testa-skarmbilder" aria-label="Permalink to &quot;Testa skärmbilder&quot;">​</a></h2><h3 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h3><ul><li>Klicka på knappar för att navigera mellan skärmar</li><li>Testa alla navigationslänkar</li><li>Verifiera att rätt skärm visas</li></ul><h3 id="inmatningsfalt" tabindex="-1">Inmatningsfält <a class="header-anchor" href="#inmatningsfalt" aria-label="Permalink to &quot;Inmatningsfält&quot;">​</a></h3><ol><li>Klicka i ett inmatningsfält</li><li>Ange ett värde med tangentbordet</li><li>Tryck Enter för att bekräfta</li><li>Verifiera att värdet uppdateras i PLC:n (via watch table)</li></ol><h3 id="knappar-och-styrning" tabindex="-1">Knappar och styrning <a class="header-anchor" href="#knappar-och-styrning" aria-label="Permalink to &quot;Knappar och styrning&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Testfall</th><th>Förväntat resultat</th></tr></thead><tbody><tr><td>Tryck Startknapp</td><td>Motor startar, indikator blir grön</td></tr><tr><td>Tryck Stoppknapp</td><td>Motor stannar, indikator blir grå</td></tr><tr><td>Ange börvärde</td><td>Värde skickas till PLC</td></tr><tr><td>Kvitteringsknapp</td><td>Larm kvitteras</td></tr></tbody></table><h2 id="testa-dynamiska-objekt" tabindex="-1">Testa dynamiska objekt <a class="header-anchor" href="#testa-dynamiska-objekt" aria-label="Permalink to &quot;Testa dynamiska objekt&quot;">​</a></h2><h3 id="indikatorer-och-lampor" tabindex="-1">Indikatorer och lampor <a class="header-anchor" href="#indikatorer-och-lampor" aria-label="Permalink to &quot;Indikatorer och lampor&quot;">​</a></h3><p>Verifiera att lampor ändrar färg korrekt:</p><ol><li>Tvinga motsvarande variabel i PLCSIM</li><li>Observera att lampan ändrar utseende</li><li>Testa alla tillstånd (normal, aktiv, fel)</li></ol><h3 id="stapeldiagram-bar-graphs" tabindex="-1">Stapeldiagram (Bar graphs) <a class="header-anchor" href="#stapeldiagram-bar-graphs" aria-label="Permalink to &quot;Stapeldiagram (Bar graphs)&quot;">​</a></h3><ol><li>Ändra det analoga värdet i watch table</li><li>Verifiera att stapeln ändrar höjd</li><li>Testa min- och max-gränser</li></ol><h3 id="trender" tabindex="-1">Trender <a class="header-anchor" href="#trender" aria-label="Permalink to &quot;Trender&quot;">​</a></h3><ol><li>Låt simulering köra en stund</li><li>Öppna trendskärmen</li><li>Verifiera att data loggas korrekt</li><li>Testa zoomfunktioner</li></ol><h2 id="testa-larmsystem" tabindex="-1">Testa larmsystem <a class="header-anchor" href="#testa-larmsystem" aria-label="Permalink to &quot;Testa larmsystem&quot;">​</a></h2><h3 id="generera-testlarm" tabindex="-1">Generera testlarm <a class="header-anchor" href="#generera-testlarm" aria-label="Permalink to &quot;Generera testlarm&quot;">​</a></h3><ol><li>I PLCSIM watch table, sätt villkoret för ett larm</li><li>Verifiera att larmet visas i HMI:ns larmlista</li><li>Kontrollera att rätt text och prioritet visas</li></ol><h3 id="kvittera-larm" tabindex="-1">Kvittera larm <a class="header-anchor" href="#kvittera-larm" aria-label="Permalink to &quot;Kvittera larm&quot;">​</a></h3><ol><li>Klicka på larmet i larmlistan</li><li>Tryck kvitteringsknappen</li><li>Verifiera att larmstatus uppdateras</li></ol><h3 id="larmhistorik" tabindex="-1">Larmhistorik <a class="header-anchor" href="#larmhistorik" aria-label="Permalink to &quot;Larmhistorik&quot;">​</a></h3><ol><li>Generera och kvittera några larm</li><li>Öppna larmhistoriken</li><li>Verifiera att alla larm loggats med rätt tidsstämpel</li></ol><h2 id="felsokning-av-hmi" tabindex="-1">Felsökning av HMI <a class="header-anchor" href="#felsokning-av-hmi" aria-label="Permalink to &quot;Felsökning av HMI&quot;">​</a></h2><h3 id="vanliga-problem" tabindex="-1">Vanliga problem <a class="header-anchor" href="#vanliga-problem" aria-label="Permalink to &quot;Vanliga problem&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Problem</th><th>Möjlig orsak</th><th>Lösning</th></tr></thead><tbody><tr><td>Inga värden visas</td><td>Kommunikationsfel</td><td>Kontrollera PLC-anslutning</td></tr><tr><td>Knapp reagerar inte</td><td>Fel taggkoppling</td><td>Verifiera tagg i properties</td></tr><tr><td>Fel färg på indikator</td><td>Fel appearance-inställning</td><td>Kontrollera animations-settings</td></tr><tr><td>Navigation fungerar inte</td><td>Saknad skärm</td><td>Verifiera Screen change-event</td></tr></tbody></table><h3 id="aktivera-diagnostik" tabindex="-1">Aktivera diagnostik <a class="header-anchor" href="#aktivera-diagnostik" aria-label="Permalink to &quot;Aktivera diagnostik&quot;">​</a></h3><ol><li>Gå till <strong>Runtime settings</strong> i HMI-egenskaperna</li><li>Aktivera <strong>Diagnostics</strong> (om tillgängligt)</li><li>Kontrollera diagnostikfönstret för felmeddelanden</li></ol><h2 id="simulering-pa-dator-vs-panel" tabindex="-1">Simulering på dator vs panel <a class="header-anchor" href="#simulering-pa-dator-vs-panel" aria-label="Permalink to &quot;Simulering på dator vs panel&quot;">​</a></h2><h3 id="skillnader-att-vara-medveten-om" tabindex="-1">Skillnader att vara medveten om <a class="header-anchor" href="#skillnader-att-vara-medveten-om" aria-label="Permalink to &quot;Skillnader att vara medveten om&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspekt</th><th>Simulering</th><th>Riktig panel</th></tr></thead><tbody><tr><td>Pekskärm</td><td>Musklick</td><td>Touch</td></tr><tr><td>Prestanda</td><td>Datorns hastighet</td><td>Panelens CPU</td></tr><tr><td>Minne</td><td>Obegränsat</td><td>Begränsat</td></tr><tr><td>Script</td><td>Full support</td><td>Kan variera</td></tr></tbody></table><h3 id="begransningar-i-simulering" tabindex="-1">Begränsningar i simulering <a class="header-anchor" href="#begransningar-i-simulering" aria-label="Permalink to &quot;Begränsningar i simulering&quot;">​</a></h3><ul><li>Extern USB-kommunikation fungerar ej</li><li>Skrivarfunktioner begränsade</li><li>Vissa systemfunktioner ej tillgängliga</li></ul><h2 id="tips-for-effektiv-hmi-testning" tabindex="-1">Tips för effektiv HMI-testning <a class="header-anchor" href="#tips-for-effektiv-hmi-testning" aria-label="Permalink to &quot;Tips för effektiv HMI-testning&quot;">​</a></h2><h3 id="checklista-for-testning" tabindex="-1">Checklista för testning <a class="header-anchor" href="#checklista-for-testning" aria-label="Permalink to &quot;Checklista för testning&quot;">​</a></h3><ul><li>[ ] Alla skärmbilder kan nås</li><li>[ ] Alla knappar fungerar</li><li>[ ] Inmatningsfält validerar korrekt</li><li>[ ] Indikatorer visar rätt status</li><li>[ ] Larm genereras och visas korrekt</li><li>[ ] Trender visar data</li><li>[ ] Användarnivåer fungerar (om implementerat)</li></ul><h3 id="dokumentera-testresultat" tabindex="-1">Dokumentera testresultat <a class="header-anchor" href="#dokumentera-testresultat" aria-label="Permalink to &quot;Dokumentera testresultat&quot;">​</a></h3><p>Skapa ett testprotokoll:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Datum: 2024-01-15</span></span>
<span class="line"><span>Testare: [Namn]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Testfall 1: Navigation</span></span>
<span class="line"><span>- Huvudskärm → Motorskärm: OK</span></span>
<span class="line"><span>- Motorskärm → Larmskärm: OK</span></span>
<span class="line"><span>- Tillbaka-knapp: OK</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Testfall 2: Motorstyrning</span></span>
<span class="line"><span>- Start motor 1: OK</span></span>
<span class="line"><span>- Stopp motor 1: OK</span></span>
<span class="line"><span>- Hastighetsjustering: OK</span></span></code></pre></div><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/109817218/updates-for-step-7-v18-s7-plcsim-v18-and-wincc-v18" target="_blank" rel="noreferrer">TIA Portal V18 Updates</a> - Uppdateringar inkl. WinCC</li></ul><h2 id="nasta-steg" tabindex="-1">Nästa steg <a class="header-anchor" href="#nasta-steg" aria-label="Permalink to &quot;Nästa steg&quot;">​</a></h2><ul><li><a href="./plcsim.html">PLCSIM</a> - PLC-simulering</li><li><a href="./kommunikationskontroll.html">Kommunikationskontroll</a> - Nätverksdiagnostik</li></ul>`,60)])])}const g=t(l,[["render",n]]);export{u as __pageData,g as default};
